174	    let m = vm.new_object();
175	    m.set_str("Buffer", Value::Obj(ctor), WEC);
176	    m.set_str("kMaxLength", Value::Num(4294967296.0), WEC);
177	    m.set_str("kStringMaxLength", Value::Num(536870888.0), WEC);
178	    let constants = vm.obj_from(vec![("MAX_LENGTH", Value::Num(4294967296.0)), ("MAX_STRING_LENGTH", Value::Num(536870888.0))]);
179	    m.set_str("constants", Value::Obj(constants), WEC);
180	    m.set_str("INSPECT_MAX_BYTES", Value::Num(50.0), WEC);
181	    for n in ["atob", "btoa", "Blob", "File"] {
182	        if let Some(v) = vm.global.get_own_str(n) {
183	            m.set_str(n, v, WEC);
184	        }
185	    }
186	    vm.def_method(&m, "isUtf8", 1, |_vm, a| {
187	        let b = match &a.arg(0) {
188	            Value::Obj(o) => ta_bytes(o),
189	            _ => Vec::new(),
190	        };
191	        Ok(Value::Bool(std::str::from_utf8(&b).is_ok()))
192	    });
193	    vm.def_method(&m, "isAscii", 1, |_vm, a| {
194	        let b = match &a.arg(0) {
195	            Value::Obj(o) => ta_bytes(o),
196	            _ => Vec::new(),
197	        };
198	        Ok(Value::Bool(b.iter().all(|x| *x < 128)))
199	    });
200	    let mv = Value::Obj(m);
201	    vm.host.builtin_cache.insert("buffer".into(), mv.clone());
202	    mv
203	}
