238	pub fn encode_string(s: &JsStr, encoding: &str) -> Vec<u8> {
239	    match encoding {
240	        "hex" => enc::hex_decode_lenient(&s.to_rust_string()),
241	        "base64" | "base64url" => enc::base64_decode_lenient(&s.to_rust_string()),
242	        "latin1" | "ascii" => s.units().iter().map(|&c| c as u8).collect(),
243	        "utf16le" => {
244	            let mut v = Vec::with_capacity(s.len() * 2);
245	            for &c in s.units() {
246	                v.push(c as u8);
247	                v.push((c >> 8) as u8);
248	            }
249	            v
250	        }
251	        _ => enc::utf16_to_utf8(s.units()),
252	    }
253	}
