255	pub fn decode_bytes(b: &[u8], encoding: &str) -> JsStr {
256	    match encoding {
257	        "hex" => JsStr::from_str(&enc::hex_encode(b)),
258	        "base64" => JsStr::from_str(&enc::base64_encode(b, false)),
259	        "base64url" => {
260	            let s = enc::base64_encode(b, true);
261	            JsStr::from_str(s.trim_end_matches('='))
262	        }
263	        "latin1" => JsStr::from_units(enc::latin1_to_utf16(b)),
264	        "ascii" => JsStr::from_units(b.iter().map(|&x| (x & 0x7f) as u16).collect()),
265	        "utf16le" => {
266	            let v: Vec<u16> = b.chunks(2).filter(|c| c.len() == 2).map(|c| c[0] as u16 | ((c[1] as u16) << 8)).collect();
267	            JsStr::from_units(v)
268	        }
269	        _ => JsStr::from_units(enc::utf8_to_utf16(b)),
270	    }
271	}
