299	/// bytes of a Buffer/TypedArray/ArrayBuffer/DataView/string
300	pub fn bytes_of(vm: &mut Vm, v: &Value) -> JsResult<Vec<u8>> {
301	    match v {
302	        Value::Obj(o) => {
303	            let is_bin = matches!(o.borrow().kind, ObjKind::TypedArray(_) | ObjKind::ArrayBuffer(_) | ObjKind::DataView(_));
304	            if is_bin {
305	                return Ok(ta_bytes(o));
306	            }
307	            let vals = crate::builtins::array::array_like_to_vec(vm, v)?;
308	            let mut out = Vec::with_capacity(vals.len());
309	            for x in vals {
310	                out.push(crate::builtins::number::to_uint32(vm.to_number(&x)?) as u8);
311	            }
312	            Ok(out)
313	        }
314	        Value::Str(s) => Ok(enc::utf16_to_utf8(s.units())),
315	        _ => vm.throw_type("argument must be a Buffer, TypedArray, or string"),
316	    }
317	}
