319	fn buffer_from(vm: &mut Vm, a: &Args) -> JsResult<Value> {
320	    let v = a.arg(0);
321	    match &v {
322	        Value::Str(s) => {
323	            let e = encoding_arg(vm, &a.arg(1))?;
324	            let b = encode_string(s, e);
325	            new_buffer_value(vm, b)
326	        }
327	        Value::Obj(o) => {
328	            let ab = match &o.borrow().kind {
329	                ObjKind::ArrayBuffer(b) => Some(b.clone()),
330	                _ => None,
331	            };
332	            if let Some(buf) = ab {
333	                // shares memory
334	                let blen = buf.borrow().bytes.len();
335	                let off = if a.arg(1).is_undefined() { 0 } else { vm.to_index(&a.arg(1))? };
336	                if off > blen {
337	                    return vm.throw_range("\"offset\" is outside of buffer bounds");
338	                }
339	                let len = if a.arg(2).is_undefined() { blen - off } else { vm.to_index(&a.arg(2))? };
340	                if off + len > blen {
341	                    return vm.throw_range("\"length\" is outside of buffer bounds");
342	                }
343	                let p = buffer_proto().unwrap();
344	                return Ok(Value::Obj(Obj::with_class(
345	                    Some(p),
346	                    ObjKind::TypedArray(Box::new(TypedArrayData { kind: TAKind::Uint8, buffer: o.clone(), buf, offset: off, length: Some(len) })),
347	                    "Uint8Array",
348	                )));
349	            }
350	            // valueOf / Symbol.toPrimitive objects returning strings
351	            let is_plain = !matches!(o.borrow().kind, ObjKind::TypedArray(_) | ObjKind::Array(_) | ObjKind::DataView(_));
352	            if is_plain {
353	                let tp = vm.get(o, &PropKey::Sym(vm.intr.sym_to_primitive.clone()), &v)?;
354	                if tp.is_callable() {
355	                    let p = vm.call(&tp, v.clone(), &[Value::str("string")])?;
356	                    if let Value::Str(s) = p {
357	                        let e = encoding_arg(vm, &a.arg(1))?;
358	                        return new_buffer_value(vm, encode_string(&s, e));
359	                    }
360	                }
361	                let ty = vm.get_str(o, "type")?;
362	                let data = vm.get_str(o, "data")?;
363	                if matches!(&ty, Value::Str(s) if s.eq_str("Buffer")) && data.is_object() {
364	                    let b = bytes_of(vm, &data)?;
365	                    return new_buffer_value(vm, b);
366	                }
367	                let len = vm.get_str(o, "length")?;
368	                if len.is_undefined() {
369	                    let d = crate::runtime::util::describe_received(vm, &v);
370	                    return vm.throw_type(format!("The first argument must be of type string or an instance of Buffer, ArrayBuffer, or Array or an Array-like Object. Received {}", d));
371	                }
372	            }
373	            let b = bytes_of(vm, &v)?;
374	            new_buffer_value(vm, b)
375	        }
376	        other => {
377	            let d = crate::runtime::util::describe_received(vm, other);
378	            let e = vm.make_error("TypeError", &format!("The first argument must be of type string or an instance of Buffer, ArrayBuffer, or Array or an Array-like Object. Received {}", d));
379	            if let Value::Obj(eo) = &e {
380	                eo.set_prop(PropKey::from_str("code"), Value::str("ERR_INVALID_ARG_TYPE"), WC);
381	            }
382	            Err(e)
383	        }
384	    }
385	}
