399	            let e = vm.make_error("TypeError", &format!("The \"size\" argument must be of type number. Received {}", d));
400	            if let Value::Obj(o) = &e {
401	                o.set_prop(PropKey::from_str("code"), Value::str("ERR_INVALID_ARG_TYPE"), WC);
402	            }
