408	fn buffer_alloc(vm: &mut Vm, a: &Args) -> JsResult<Value> {
409	    let n = size_arg(vm, &a.arg(0))?;
410	    let b = new_buffer(vm, vec![0; n])?;
411	    let fill = a.arg(1);
412	    if !fill.is_undefined() && n > 0 {
413	        let pattern = match &fill {
414	            Value::Str(s) => {
415	                let e = encoding_arg(vm, &a.arg(2))?;
416	                encode_string(s, e)
417	            }
418	            Value::Num(x) => vec![crate::builtins::number::to_uint32(*x) as u8],
419	            other => bytes_of(vm, other)?,
420	        };
421	        if !pattern.is_empty() {
422	            let data: Vec<u8> = (0..n).map(|i| pattern[i % pattern.len()]).collect();
423	            write_bytes(&b, 0, &data);
424	        }
425	    }
426	    Ok(Value::Obj(b))
427	}
