434	pub fn write_bytes(o: &Obj, start: usize, data: &[u8]) {
435	    let b = o.borrow();
436	    if let ObjKind::TypedArray(t) = &b.kind {
437	        let len = t.len();
438	        let mut bb = t.buf.borrow_mut();
439	        for (i, x) in data.iter().enumerate() {
440	            if start + i >= len {
441	                break;
442	            }
443	            bb.bytes[t.offset + start + i] = *x;
444	        }
445	    }
446	}
