522	fn buf_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
523	    let (o, b) = this_bytes(vm, &a.this)?;
524	    let s = vm.to_string(&a.arg(0))?;
525	    let mut offset = 0usize;
526	    let mut length = b.len();
527	    let mut encv = Value::Undefined;
528	    match a.arg(1) {
529	        Value::Str(_) => encv = a.arg(1),
530	        Value::Undefined => {}
531	        v => {
532	            offset = vm.to_index(&v)?;
533	            match a.arg(2) {
534	                Value::Str(_) => encv = a.arg(2),
535	                Value::Undefined => {}
536	                l => {
537	                    length = vm.to_index(&l)?;
538	                    encv = a.arg(3);
539	                }
540	            }
541	        }
542	    }
543	    if offset > b.len() {
