573	fn buf_compare(vm: &mut Vm, a: &Args) -> JsResult<Value> {
574	    let (_, x) = this_bytes(vm, &a.this)?;
575	    let (_, y) = this_bytes(vm, &a.arg(0))?;
576	    let ts = clamp_idx(vm, &a.arg(1), y.len(), 0)?;
577	    let te = clamp_idx(vm, &a.arg(2), y.len(), y.len())?;
