579	    let se = clamp_idx(vm, &a.arg(4), x.len(), x.len())?;
580	    let xs = if ss < se { &x[ss..se] } else { &x[0..0] };
581	    let ys = if ts < te { &y[ts..te] } else { &y[0..0] };
582	    Ok(Value::Num(match xs.cmp(ys) {
583	        std::cmp::Ordering::Less => -1.0,
584	        std::cmp::Ordering::Equal => 0.0,
585	        std::cmp::Ordering::Greater => 1.0,
586	    }))
