592	        _ => return vm.throw_type("argument must be a buffer"),
593	    };
594	    let (len, buffer, buf, offset) = match &o.borrow().kind {
595	        ObjKind::TypedArray(t) => (t.len(), t.buffer.clone(), t.buf.clone(), t.offset),
596	        _ => unreachable!(),
597	    };
598	    let rel = |vm: &mut Vm, v: &Value, d: usize| -> JsResult<usize> {
599	        if v.is_undefined() {
600	            return Ok(d);
601	        }
602	        let n = vm.to_integer_or_infinity(v)?;
603	        Ok(if n < 0.0 { (len as f64 + n).max(0.0) as usize } else { (n as usize).min(len) })
604	    };
605	    let s = rel(vm, &a.arg(0), 0)?;
606	    let e = rel(vm, &a.arg(1), len)?;
607	    let e = e.max(s);
608	    let p = o.borrow().proto.clone();
609	    Ok(Value::Obj(Obj::with_class(p, ObjKind::TypedArray(Box::new(TypedArrayData { kind: TAKind::Uint8, buffer, buf, offset: offset + s, length: Some(e - s) })), "Uint8Array")))
610	}
