612	fn buf_index_of(vm: &mut Vm, a: &Args, last: bool, includes: bool) -> JsResult<Value> {
613	    let (_, b) = this_bytes(vm, &a.this)?;
614	    let needle: Vec<u8> = match &a.arg(0) {
615	        Value::Str(s) => {
616	            let e = encoding_arg(vm, &a.arg(2))?;
617	            encode_string(s, e)
618	        }
619	        Value::Num(n) => vec![crate::builtins::number::to_uint32(*n) as u8],
620	        other => bytes_of(vm, other)?,
621	    };
622	    let len = b.len() as f64;
623	    let start = if a.arg(1).is_undefined() {
624	        if last {
625	            len
626	        } else {
627	            0.0
628	        }
629	    } else {
630	        let n = vm.to_integer_or_infinity(&a.arg(1))?;
631	        if n < 0.0 {
632	            (len + n).max(0.0)
633	        } else {
634	            n
635	        }
636	    };
637	    let result: f64 = if needle.is_empty() {
638	        start.min(len)
639	    } else if last {
640	        let mut i = (start as i64).min(b.len() as i64 - needle.len() as i64);
641	        let mut r = -1.0;
642	        while i >= 0 {
643	            let iu = i as usize;
644	            if b[iu..iu + needle.len()] == needle[..] {
645	                r = i as f64;
646	                break;
647	            }
648	            i -= 1;
649	        }
650	        r
651	    } else {
652	        let mut r = -1.0;
653	        let mut i = start as usize;
654	        while i + needle.len() <= b.len() {
655	            if b[i..i + needle.len()] == needle[..] {
656	                r = i as f64;
657	                break;
658	            }
659	            i += 1;
660	        }
661	        r
662	    };
663	    if includes {
664	        return Ok(Value::Bool(result >= 0.0));
665	    }
666	    Ok(Value::Num(result))
667	}
