669	fn buf_fill(vm: &mut Vm, a: &Args) -> JsResult<Value> {
670	    let (o, b) = this_bytes(vm, &a.this)?;
671	    let mut encv = Value::Undefined;
672	    let (s, e) = match a.arg(1) {
673	        Value::Str(_) => {
674	            encv = a.arg(1);
675	            (0, b.len())
676	        }
677	        v => {
