707	fn buf_copy(vm: &mut Vm, a: &Args) -> JsResult<Value> {
708	    let (_, src) = this_bytes(vm, &a.this)?;
709	    let (t, tb) = this_bytes(vm, &a.arg(0))?;
710	    let ts = clamp_idx(vm, &a.arg(1), tb.len(), 0)?;
711	    let ss = clamp_idx(vm, &a.arg(2), src.len(), 0)?;
712	    let se = clamp_idx(vm, &a.arg(3), src.len(), src.len())?;
713	    if ss >= se || ts >= tb.len() {
714	        return Ok(Value::Num(0.0));
715	    }
716	    let n = (se - ss).min(tb.len() - ts);
717	    write_bytes(&t, ts, &src[ss..ss + n]);
