741	fn offset_arg(vm: &mut Vm, v: &Value, len: usize, size: usize) -> JsResult<usize> {
742	    let off = if v.is_undefined() { 0.0 } else { vm.to_number(v)? };
743	    if off.fract() != 0.0 || off < 0.0 || off as usize + size > len {
744	        if len < size {
745	            let e = vm.make_error("RangeError", "Attempt to access memory outside buffer bounds");
746	            if let Value::Obj(o) = &e {
747	                o.set_prop(PropKey::from_str("code"), Value::str("ERR_BUFFER_OUT_OF_BOUNDS"), WC);
748	            }
749	            return Err(e);
750	        }
751	        return Err(out_of_range(vm, "offset", &format!(">= 0 and <= {}", len - size), &crate::numconv::number_to_string(off)));
752	    }
753	    Ok(off as usize)
754	}
