763	        (0, 1) => TAKind::Uint8,
764	        (1, 1) => TAKind::Int8,
765	        (0, 2) => TAKind::Uint16,
766	        (1, 2) => TAKind::Int16,
767	        (0, 4) => TAKind::Uint32,
768	        (1, 4) => TAKind::Int32,
769	        (2, _) => TAKind::Float32,
