777	fn buf_write_num(vm: &mut Vm, a: &Args) -> JsResult<Value> {
778	    let kind = a.slot(0).as_num().unwrap() as u8;
779	    let size = a.slot(1).as_num().unwrap() as usize;
780	    let little = a.slot(2).truthy();
781	    let (o, b) = this_bytes(vm, &a.this)?;
782	    let off = offset_arg(vm, &a.arg(1), b.len(), size)?;
783	    let tk = match (kind, size) {
784	        (0, 1) => TAKind::Uint8,
785	        (1, 1) => TAKind::Int8,
786	        (0, 2) => TAKind::Uint16,
787	        (1, 2) => TAKind::Int16,
788	        (0, 4) => TAKind::Uint32,
789	        (1, 4) => TAKind::Int32,
790	        (2, _) => TAKind::Float32,
791	        (3, _) => TAKind::Float64,
792	        (4, _) => TAKind::BigInt64,
793	        _ => TAKind::BigUint64,
794	    };
795	    let v = if kind >= 4 {
796	        Value::BigInt(vm.to_bigint(&a.arg(0))?)
797	    } else {
798	        let n = vm.to_number(&a.arg(0))?;
799	        if kind <= 1 {
800	            let (lo, hi) = match (kind, size) {
801	                (0, s) => (0.0, 2f64.powi(8 * s as i32) - 1.0),
802	                (_, s) => (-(2f64.powi(8 * s as i32 - 1)), 2f64.powi(8 * s as i32 - 1) - 1.0),
803	            };
804	            if n < lo || n > hi || n.is_nan() {
805	                let range = if kind == 0 { format!(">= 0 and <= {}", crate::numconv::number_to_string(hi)) } else { format!(">= {} and <= {}", crate::numconv::number_to_string(lo), crate::numconv::number_to_string(hi)) };
806	                return Err(out_of_range(vm, "value", &range, &crate::numconv::number_to_string(n)));
807	            }
808	        }
809	        Value::Num(n)
810	    };
811	    let mut tmp = vec![0u8; size];
812	    crate::builtins::typedarray::write_elem(&mut tmp, 0, tk, &v, little);
813	    write_bytes(&o, off, &tmp);
814	    Ok(Value::Num((off + size) as f64))
815	}
