817	fn buf_read_var(vm: &mut Vm, a: &Args) -> JsResult<Value> {
818	    let signed = a.slot(0).truthy();
819	    let little = a.slot(1).truthy();
820	    let (_, b) = this_bytes(vm, &a.this)?;
821	    let bl = vm.to_number(&a.arg(1))? as usize;
822	    let off = offset_arg(vm, &a.arg(0), b.len(), bl)?;
823	    let bytes = &b[off..off + bl];
824	    let mut v: u64 = 0;
825	    if little {
826	        for (i, x) in bytes.iter().enumerate() {
827	            v |= (*x as u64) << (8 * i);
828	        }
829	    } else {
830	        for x in bytes {
831	            v = (v << 8) | *x as u64;
832	        }
833	    }
834	    let r = if signed && bl < 8 && v & (1 << (8 * bl - 1)) != 0 { v as i64 - (1i64 << (8 * bl)) } else { v as i64 };
835	    Ok(Value::Num(r as f64))
836	}
