838	fn buf_write_var(vm: &mut Vm, a: &Args) -> JsResult<Value> {
839	    let little = a.slot(1).truthy();
840	    let (o, b) = this_bytes(vm, &a.this)?;
841	    let n = vm.to_number(&a.arg(0))?;
842	    let bl = vm.to_number(&a.arg(2))? as usize;
843	    let off = offset_arg(vm, &a.arg(1), b.len(), bl)?;
844	    let v = n as i64 as u64;
845	    let mut tmp = vec![0u8; bl];
846	    for i in 0..bl {
847	        let byte = ((v >> (8 * i)) & 0xff) as u8;
848	        if little {
849	            tmp[i] = byte;
850	        } else {
851	            tmp[bl - 1 - i] = byte;
852	        }
853	    }
854	    write_bytes(&o, off, &tmp);
855	    Ok(Value::Num((off + bl) as f64))
856	}
