884	fn utf8_complete_prefix(b: &[u8]) -> usize {
885	    // length of the longest prefix that does not end in an incomplete sequence
886	    let n = b.len();
887	    let mut i = n;
888	    let mut back = 0;
889	    while i > 0 && back < 4 {
890	        i -= 1;
891	        back += 1;
892	        let c = b[i];
893	        if c & 0xC0 == 0x80 {
894	            continue;
895	        }
896	        let need = if c & 0x80 == 0 {
897	            1
898	        } else if c & 0xE0 == 0xC0 {
899	            2
900	        } else if c & 0xF0 == 0xE0 {
901	            3
902	        } else if c & 0xF8 == 0xF0 {
903	            4
904	        } else {
905	            1
906	        };
907	        return if n - i >= need { n } else { i };
908	    }
909	    n
910	}
