912	fn sd_write(vm: &mut Vm, a: &Args) -> JsResult<Value> {
913	    let data = bytes_of(vm, &a.arg(0))?;
914	    let st = match &a.this {
915	        Value::Obj(o) => o.clone(),
916	        _ => return vm.throw_type("incompatible receiver"),
917	    };
918	    let b = st.borrow();
919	    let s = match &b.kind {
920	        ObjKind::Host(h) => h.downcast_ref::<SdState>().unwrap(),
921	        _ => return Ok(Value::str("")),
922	    };
923	    let mut p = s.pending.borrow_mut();
924	    p.extend(data);
925	    let out = match s.encoding {
926	        "utf8" => {
927	            let k = utf8_complete_prefix(&p);
928	            let r = decode_bytes(&p[..k], "utf8");
929	            p.drain(..k);
930	            r
931	        }
932	        "utf16le" => {
933	            let k = p.len() / 2 * 2;
934	            let r = decode_bytes(&p[..k], "utf16le");
935	            p.drain(..k);
936	            r
937	        }
938	        "base64" => {
939	            let k = p.len() / 3 * 3;
940	            let r = decode_bytes(&p[..k], "base64");
941	            p.drain(..k);
942	            r
943	        }
944	        e => {
945	            let r = decode_bytes(&p, e);
946	            p.clear();
947	            r
948	        }
949	    };
950	    Ok(Value::Str(out))
951	}
952	
953	fn sd_end(vm: &mut Vm, a: &Args) -> JsResult<Value> {
954	    let mut prefix = JsStr::empty();
955	    if !a.arg(0).is_undefined() {
956	        if let Value::Str(s) = sd_write(vm, a)? {
957	            prefix = s;
958	        }
959	    }
960	    let st = match &a.this {
961	        Value::Obj(o) => o.clone(),
962	        _ => return vm.throw_type("incompatible receiver"),
963	    };
964	    let b = st.borrow();
965	    let rest = match &b.kind {
966	        ObjKind::Host(h) => {
967	            let s = h.downcast_ref::<SdState>().unwrap();
968	            let mut p = s.pending.borrow_mut();
969	            let r = if p.is_empty() { JsStr::empty() } else { decode_bytes(&p, s.encoding) };
970	            p.clear();
971	            r
972	        }
973	        _ => JsStr::empty(),
974	    };
975	    Ok(Value::Str(JsStr::concat(&prefix, &rest)))
976	}
