    let ev = vm.get_str(&o, "_events")?;
    match ev {
        Value::Obj(e) => Ok(e),
        _ => {
            init_emitter(vm, &o);
            match vm.get_str(&o, "_events")? {
                Value::Obj(e) => Ok(e),
                _ => vm.throw_type("cannot initialize events"),
            }
        }
    }
}

