    /// Create a native function object.
    pub fn native_fn(&self, name: &str, len: u32, f: NativeFn) -> Obj {
        let o = Obj::with_class(
            Some(self.intr.function_proto.clone()),
            ObjKind::Native(NativeFunc { f, slots: Vec::new(), is_ctor: false, name: "" }),
            "Function",
        );
