        func
    }

    pub fn def_sym_method(&self, target: &Obj, sym: &Sym, name: &str, len: u32, f: NativeFn) -> Obj {
        let func = self.native_fn(name, len, f);
        target.set_prop(PropKey::Sym(sym.clone()), Value::Obj(func.clone()), WC);
