        },
        K::Ab(false) => Ok(ta_bytes(o)),
        K::Ab(true) => vm.throw_type("Buffer.from: unsupported value"),
        K::Dv => Ok(Vec::new()),
        K::Other => {
            let len = getp(vm, v, "length")?;
            if len.is_undefined() {
                return vm.throw_type("Buffer.from: unsupported value");
            }
            let n = vm.to_length(&len)? as usize;
            check_len(vm, n)?;
