/// Deliver `cb(err)` or `cb(null, ...results)` from a microtask.
fn defer_cb(vm: &mut Vm, cb: &Value, r: Result<Vec<Value>, Value>) {
    let mut slots = vec![cb.clone()];
    match r {
        Ok(vals) => {
            slots.push(Value::Bool(true));
            slots.extend(vals);
        }
        Err(e) => {
            slots.push(Value::Bool(false));
            slots.push(e);
        }
    }
    let job = closure(vm, deferred_cb_job, slots);
    queue_microtask(vm, job);
}

fn deferred_cb_job(vm: &mut Vm, a: &Args) -> JsResult<Value> {
    let cb = a.slot(0);
    let ok = a.slot(1).truthy();
    let mut args = Vec::new();
    let mut i = 2;
    loop {
        if let ObjKind::Native(n) = &a.callee.borrow().kind {
            if i >= n.slots.len() {
                break;
            }
        }
        args.push(a.slot(i));
        i += 1;
    }
    let call_args: Vec<Value> = if ok {
        let mut v = vec![Value::Null];
        v.extend(args);
        v
    } else {
        args
    };
    if !cb.is_callable() {
        let m = format!("{} is not a function", if a.slot(0).is_undefined() { "cb" } else { "cb" });
        return vm.throw_type(m);
    }
    vm.call(&cb, Value::Undefined, &call_args)
}

