  for (const enc of [undefined, 'hex', 'base64', 'base64url', 'latin1', 'binary', 'buffer', 'utf8', 'ascii', 'ucs2', 'HEX', null, '']) {
    const d = c.createHash(alg).update('The quick brown fox').update(Buffer.from([1, 2, 3])).digest(enc);
