const c = require('crypto');
const fs = require('fs');
const fx = f => fs.readFileSync('/tmp/zcagent/fx/' + f, 'utf8');
const log = (...a) => console.log(...a);
const keys = {};
for (const f of ['rsa512.pem', 'rsa1024.pem', 'rsa1024_pkcs1.pem', 'rsa2048.pem', 'ec_sec1.pem', 'rsapss.pem', 'ec_key.pem', 'ed_key.pem', 'rsa_key.pem', 'leaf_key.pem']) {
  try {
    const k = c.createPrivateKey(fx(f));
    keys[f] = k;
    const p = c.createPublicKey(k);
    log(f, k.type, k.asymmetricKeyType, JSON.stringify(k.asymmetricKeyDetails, (_, v) => typeof v === 'bigint' ? v.toString() + 'n' : v));
    log('  spki', p.export({format: 'der', type: 'spki'}).toString('base64').slice(0, 60));
    log('  pkcs8', k.export({format: 'der', type: 'pkcs8'}).toString('hex').slice(0, 60), k.export({format: 'pem', type: 'pkcs8'}).length);
    log('  jwk', JSON.stringify(p.export({format: 'jwk'})).slice(0, 120));
    log('  jwkpriv', Object.keys(k.export({format: 'jwk'})).join());
    try { log('  pkcs1', k.export({format: 'pem', type: 'pkcs1'}).split('\n')[0], p.export({format: 'pem', type: 'pkcs1'}).split('\n')[0]); } catch (e) { log('  pkcs1 err', e.message); }
    try { log('  sec1', k.export({format: 'pem', type: 'sec1'}).split('\n')[0]); } catch (e) { log('  sec1 err', e.message); }
    log('  equals', k.equals(c.createPrivateKey(k.export({format: 'pem', type: 'pkcs8'}))), p.equals(c.createPublicKey(p.export({format: 'jwk'}) && {key: p.export({format: 'jwk'}), format: 'jwk'})));
  } catch (e) { log(f, 'ERR', e.message); }
}
for (const f of ['ec384.pem', 'ed448.pem', 'dsa.pem', 'enc.pem']) {
  try { c.createPrivateKey(fx(f)); log(f, 'ok'); } catch (e) { log(f, 'ERR', e.name, e.message); }
  try { c.createPublicKey(fx(f)); log(f, 'pub ok'); } catch (e) { log(f, 'pub ERR', e.name, e.message); }
}
const msg = Buffer.from('message to sign');
// deterministic signatures: RSA PKCS1 and Ed25519
for (const f of ['rsa512.pem', 'rsa1024.pem', 'rsa2048.pem']) {
  for (const d of ['sha1', 'sha256', 'sha384', 'sha512', 'md5', 'RSA-SHA256', 'sha256WithRSAEncryption']) {
    try {
      const s = c.sign(d, msg, keys[f]);
      log(f, d, s.toString('base64').slice(0, 40), c.verify(d, msg, c.createPublicKey(keys[f]), s), c.verify(d, Buffer.from('x'), keys[f], s));
    } catch (e) { log(f, d, 'ERR', e.message); }
  }
  const ss = c.createSign('SHA256').update('message ').update('to sign').sign(keys[f], 'hex');
  log(f, 'createSign', ss.slice(0, 40), c.createVerify('sha256').update(msg).verify(c.createPublicKey(keys[f]), ss, 'hex'));
  const pss = c.sign('sha256', msg, {key: keys[f], padding: c.constants.RSA_PKCS1_PSS_PADDING, saltLength: 20});
  log(f, 'pss', pss.length, c.verify('sha256', msg, {key: keys[f], padding: 6, saltLength: 20}, pss), c.verify('sha256', msg, {key: keys[f], padding: 6}, pss));
  const ct = c.publicEncrypt(c.createPublicKey(keys[f]), Buffer.from('secret'));
  log(f, 'oaep', ct.length, c.privateDecrypt(keys[f], ct).toString());
  const ct2 = c.publicEncrypt({key: keys[f], padding: c.constants.RSA_PKCS1_PADDING}, Buffer.from('secret2'));
  try { c.privateDecrypt({key: keys[f], padding: 1}, ct2); } catch (e) { log(f, 'pkcs1 decrypt', e.name, e.message); }
  const ct3 = c.publicEncrypt({key: keys[f], oaepHash: 'sha256', oaepLabel: Buffer.from('L')}, Buffer.from('lab'));
  log(f, 'oaep256', c.privateDecrypt({key: keys[f], oaepHash: 'sha256', oaepLabel: Buffer.from('L')}, ct3).toString());
  const pe = c.privateEncrypt(keys[f], Buffer.from('signed-ish'));
  log(f, 'privateEncrypt', pe.toString('hex').slice(0, 32), c.publicDecrypt(c.createPublicKey(keys[f]), pe).toString());
}
const ed = keys['ed_key.pem'];
const es = c.sign(null, msg, ed);
log('ed25519', es.toString('hex'), c.verify(null, msg, ed, es), c.verify(undefined, msg, c.createPublicKey(ed), es));
const ec = keys['ec_sec1.pem'];
const ecs = c.sign('sha256', msg, ec);
log('ec', ecs.length > 60, c.verify('sha256', msg, ec, ecs), c.verify('sha256', msg, {key: ec, dsaEncoding: 'ieee-p1363'}, c.sign('sha256', msg, {key: ec, dsaEncoding: 'ieee-p1363'})));
// X509
for (const f of ['ec_cert.pem', 'ed_cert.pem', 'rsa_cert.pem', 'leaf_cert.pem', 'attr_cert.pem', 'rsa_sha1.pem', 'rsa_md5.pem', 'ec_sha256.pem', 'rsa_pss.pem', 'ca1.pem']) {
  try {
    const x = new c.X509Certificate(fx(f));
    log(f, Object.keys(x).join());
    log('  ', x.serialNumber, JSON.stringify(x.subject), JSON.stringify(x.issuer), x.validFrom, x.validTo, x.validFromDate.toISOString());
    log('  ', x.fingerprint, x.fingerprint256.slice(0, 20), x.ca, x.subjectAltName, x.keyUsage, x.publicKey.asymmetricKeyType, x._signatureAlgorithm);
    log('  ', x.verify(x.publicKey), x.checkIssued(x), x.checkHost('example.com'), x.checkEmail('a@b.c'), x.checkIP('127.0.0.1'), x.toString().length, JSON.stringify(x).length);
  } catch (e) { log(f, 'ERR', e.name, e.message); }
}

