const c = require('crypto');
const log = (...a) => console.log(...a);
// async ordering
c.generateKeyPair('ed25519', (e, pub, priv) => log('gkp cb', e, pub.type, priv.type, arguments.length));
c.generateKeyPair('ec', {namedCurve: 'P-256', publicKeyEncoding: {type: 'spki', format: 'pem'}}, (e, pub, priv) => log('gkp ec', typeof pub, priv.type));
c.generateKeyPair('dsa', {}, (e) => log('gkp err', e.message));
try { c.generateKeyPair('ed25519'); } catch (e) { log('gkp nocb', e.message); }
c.sign(null, Buffer.from('x'), c.generateKeyPairSync('ed25519').privateKey, (e, s) => log('sign cb', e, s.length));
