/// What `subarray` returned in `stringFromBytes` / `slice`: unsigned byte elements, or other
/// element values (with the raw bytes when it is a typed array).
enum Sub {
    Bytes(Vec<u8>),
    Elems { vals: Vec<f64>, raw: Option<Vec<u8>> },
}

impl Sub {
    /// The bytes `new Uint8Array(sub)` would hold.
    fn into_bytes(self) -> Vec<u8> {
        match self {
            Sub::Bytes(b) => b,
            Sub::Elems { vals, .. } => vals.into_iter().map(to_u8).collect(),
        }
    }
}

fn to_i32(f: f64) -> i32 {
    crate::builtins::number::to_uint32(f) as i32
}

/// The reference's generic decoders over element values (non-byte typed arrays and
/// array-likes): hex uses `v.toString(16)`, latin1 `String.fromCharCode`, etc.
fn decode_elems(vals: &[f64], e: Enc) -> Vec<u16> {
    match e {
        Enc::Hex => {
            let mut s = String::new();
            for &v in vals {
                let h = crate::numconv::number_to_string_radix(v, 16);
                if h.chars().count() < 2 {
                    s.push('0');
                }
                s.push_str(&h);
            }
            s.encode_utf16().collect()
        }
        Enc::Base64 | Enc::Base64Url => {
            let b: Vec<u8> = vals.iter().map(|&v| to_u8(v)).collect();
            decode_units(&b, e)
        }
        Enc::Latin1 => vals.iter().map(|&v| to_i32(v) as u16).collect(),
        Enc::Ascii => vals.iter().map(|&v| (to_i32(v) & 0x7f) as u16).collect(),
        Enc::Ucs2 => vals.chunks_exact(2).map(|p| (to_i32(p[0]) | (to_i32(p[1]) << 8)) as u16).collect(),
        Enc::Utf8 => Vec::new(),
    }
}

