const zlib = require('zlib');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const util = require('util');
const dir = '/workspace/assets/test_runtime_compression';
const sha = b => crypto.createHash('sha256').update(b).digest('hex');
const md5b64 = b => crypto.createHash('md5').update(b).digest('base64');
const kind = f => f.endsWith('.gz') ? 'gunzip' : f.endsWith('.zz') ? 'inflate' : f.endsWith('.raw') ? 'inflateRaw' : f.endsWith('.br') ? 'brotliDecompress' : f.endsWith('.zst') ? 'zstdDecompress' : null;
const cap = s => s[0].toUpperCase() + s.slice(1);
const files = fs.readdirSync(dir).filter(kind).sort();
(async () => {
  for (const f of files) {
    const k = kind(f);
    const data = fs.readFileSync(path.join(dir, f));
    const res = [];
    // sync
    try { const o = zlib[k + 'Sync'](data); res.push('sync:' + o.length + ':' + sha(o).slice(0, 16)); } catch (e) { res.push('sync-err:' + e.message); }
    // callback
    res.push(await new Promise(r => zlib[k](data, (e, o) => r(e ? 'cb-err:' + e.message : 'cb:' + o.length + ':' + md5b64(o)))));
    // promisify
    try { const o = await util.promisify(zlib[k])(data); res.push('p:' + o.length); } catch (e) { res.push('p-err:' + e.message); }
    // stream from file
    res.push(await new Promise(r => {
      const chunks = [];
      const st = fs.createReadStream(path.join(dir, f), {highWaterMark: 1024}).pipe(zlib['create' + cap(k)]());
      st.on('data', c => chunks.push(c));
      st.on('error', e => r('s-err:' + e.message));
      st.on('end', () => { const o = Buffer.concat(chunks); r('s:' + chunks.length + ':' + o.length + ':' + sha(o).slice(0, 12)); });
    }));
    // manual chunked writes
    res.push(await new Promise(r => {
      const st = new zlib[cap(k)]();
      let n = 0;
      st.on('data', c => n += c.length);
      st.on('error', e => r('w-err:' + e.message));
      st.on('finish', () => {});
      st.on('end', () => r('w:' + n));
      for (let i = 0; i < data.length; i += 100) st.write(data.subarray(i, i + 100));
      st.end();
    }));
    // for await
    try {
      const st = zlib['create' + cap(k)]();
      st.end(data);
      let n = 0;
      for await (const c of st) n += c.length;
      res.push('fa:' + n);
    } catch (e) { res.push('fa-err:' + e.message); }
    console.log(f, res.join(' '));
  }
  // compress + compare to originals
  const text = fs.readFileSync(path.join(dir, 'random.bin'));
  for (const c of ['gzip', 'deflate', 'deflateRaw', 'brotliCompress', 'zstdCompress']) {
    const o = zlib[c + 'Sync'](text);
    console.log(c, o.length, sha(o));
    const so = await new Promise(r => { const chunks = []; const st = zlib['create' + cap(c)](); st.on('data', d => chunks.push(d)); st.on('end', () => r(Buffer.concat(chunks))); st.end(text); });
    console.log(c, 'stream', so.equals(o));
  }
  console.log(zlib.crc32(text), zlib.crc32(text.toString('latin1')), crypto.createHash('sha1').update(text).digest('hex'));
})();

