48	}
49	
50	thread_local! {
51	    static ST: RefCell<State> = RefCell::new(State::default());
52	    static TOBYTES_CALLS: Cell<u32> = Cell::new(0);
53	    static DIGEST_CALLS: Cell<u32> = Cell::new(0);
