70	/// Frames of a `return f(...)` tail call: none while the caller is interpreted.
71	fn tail<'a>(calls: u32, name: &'a str) -> Vec<&'a str> {
72	    if calls >= TIER_UP_CALLS {
73	        vec![name]
74	    } else {
75	        vec![]
76	    }
77	}
78	
79	fn st<R>(f: impl FnOnce(&State) -> R) -> R {
80	    ST.with(|s| f(&s.borrow()))
81	}
