92	    vm.set_prop_of(v, key(k), x, true)
93	}
94	
95	fn call_member(vm: &mut Vm, x: &Value, prop: &str, args: &[Value]) -> JsResult<Value> {
96	    let f = vm.get_prop_of(x, &key(prop))?;
97	    if !f.is_callable() {
98	        let m = buffer::not_callable_msg(true, prop, &f);
99	        return vm.throw_type(m);
100	    }
101	    vm.call(&f, x.clone(), args)
102	}
